'use strict';

// MAIN //

/**
* Applies fixed alpha=-1 in the original selected-triangle DSYR order.
* @private
* @param {string|integer} uplo - selected triangle
* @param {NonNegativeInteger} KD - bandwidth
* @param {NonNegativeInteger} j - factor step
* @param {NonNegativeInteger} count - helper count
* @param {Float64Array} AB - compact band storage
* @param {integer} r - band row stride
* @param {integer} c - band column stride
* @param {integer} o - band offset
* @returns {void}
*/
function rank( uplo, KD, j, count, AB, r, c, o ) {
	var value;
	var index;
	var temp;
	var row;
	var q;
	var i;
	for ( q = 0; (q < count); q += 1 ) {
		index = ( (uplo === 121) ) ? ((o+((((KD-1)-q))*r))+((((j+1)+q))*c)) : ((o+(((1+q))*r))+(j*c));
		value = AB[ index ];
		if ( (value !== 0) ) {
			temp = ((-1)*value);
			if ( (uplo === 121) ) {
				for ( i = 0; (i <= q); i += 1 ) {
					row = ((KD-q)+i);
					index = ((o+(row*r))+((((j+1)+q))*c));
					AB[index] += (AB[((o+((((KD-1)-i))*r))+((((j+1)+i))*c))]*temp);
				}
			} else {
				for ( i = q; (i < count); i += 1 ) {
					index = ((o+(((i-q))*r))+((((j+1)+q))*c));
					AB[index] += (AB[((o+(((1+i))*r))+(j*c))]*temp);
				}
			}
		}
	}
}


// EXPORTS //

module.exports = rank;
